// Duck Hunt - a Desk Widgets community widget.
//
// Ported from the XNA game in CSharp-Duck-Hunt (Game1.cs + Duck.cs). The original ran in a
// 1100 x 700 window and was driven by an Xbox pad; the ported logic still works in that space
// and the whole screen is scaled once at draw time. Only the input, the frame pump, the themes
// and the wide layout are new.
//
//   move the pointer   aim
//   left click         shoot, and start a new game once it is over
//   right click        the widget menu (New Game, Theme, Appearance, Size, ...)
//   drag the bezel     move the widget - the screen itself is the trigger, so you drag the frame
//
// Three card sizes. Compact and Standard keep the game's own 11:7 shape. Large is a wide slot,
// and rather than stretching the ducks to fill it the world itself gets wider: GameH stays 700
// and GameW grows, so there is more sky and the duck has further to fly. Sprites keep their
// true proportions at every size; only the painted backdrop stretches.
//
// Art and sound are the original game's, re-encoded small enough to live in one source file
// (the host caps a plugin at 512 KB): sprites as PNG, sounds as mono 11 kHz 16-bit WAV.
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Drawing.Text;
using System.IO;
using System.Media;
using System.Windows.Forms;
using DeskWidgets;
using DeskWidgets.Widgets;

[DeskWidget(Name = "Duck Hunt", Description = "The NES classic on your desktop. Aim with the mouse, left click to shoot.")]
public sealed class DuckHuntWidget : CardWidget
{
    const int BaseW = 1100, GameH = 700;  // the original game's coordinate space
    const float BaseCardH = 243.27f;      // the 11:7 card height for a 364 pt wide card
    const float StepMs = 1000f / 60f;     // the fixed step the ported logic was written against
    const int FrameMs = 33;               // render rate while someone is playing
    const int IdleMs = 2000;              // keep running this long after the pointer leaves
    const int CoveredMs = 1000;           // buried under other windows: just re-check

    // ---- ported Game1 state ----
    Duck quack;
    Rectangle dogRect, dogSrc, retRect, exRect, shotRect, endDogRect, floraRect;
    Rectangle[] pointDuckRect, cloudRect;
    Point center;
    float timer, jumpTime, accum;
    int currentFrame, isShooting, score, posScore;
    int hitX, scoreX;        // HUD text columns, which move with the backdrop
    bool dogGone;

    // ---- widget plumbing ----
    bool started, introStarted;
    int lastTickAt, lastRenderAt, lastMouseAt;
    int layoutFor = -1;      // the world width the rectangles above were laid out for

    public DuckHuntWidget(Section s) : base(s, CardSize.Medium)
    {
        NewGame();
    }

    // ---- card sizes ----
    // Compact and Standard are the game's own 11:7 shape. Large is the wide one.
    SizeF CardPt()
    {
        string id = Settings.Get("size", "standard");
        if (id == "compact") return new SizeF(364f, BaseCardH);
        if (id == "large") return new SizeF(744f, 333f);
        return new SizeF(455f, 304f);
    }

    // One zoom for the chrome, taken from whichever axis is tighter, so the bezel on the short
    // wide card does not eat the screen.
    float Z
    {
        get
        {
            SizeF c = CardPt();
            return Dpi * Math.Min(c.Width / 364f, c.Height / BaseCardH);
        }
    }

    float Bezel { get { return Z * 16f; } }

    protected override Size Measure()
    {
        SizeF c = CardPt();
        return new Size((int)Math.Round(c.Width * Dpi), (int)Math.Round(c.Height * Dpi));
    }

    RectangleF ScreenRect()
    {
        Size c = Measure();
        float b = Bezel;
        return new RectangleF(b, b, c.Width - 2 * b, c.Height - 2 * b);
    }

    // The world is as wide as the screen's shape needs, never narrower than the original.
    public int GW
    {
        get
        {
            RectangleF s = ScreenRect();
            if (s.Height <= 0) return BaseW;
            int w = (int)Math.Round(GameH * s.Width / s.Height);
            return w < BaseW ? BaseW : w;
        }
    }

    // ---- settings ----
    protected override string DefaultFace { get { return "dark"; } }

    // Vibrant needs the host's private frosted-wallpaper pass, which a plugin cannot call, so
    // this widget offers the two faces it can actually render properly.
    protected override string[][] AppearanceChoices
    {
        get { return new[] { new[] { "dark", "Dark" }, new[] { "light", "Light" } }; }
    }

    string Theme { get { return Settings.Get("theme", "classic"); } }
    bool Muted { get { return Settings.GetBool("mute", false); } }
    bool HidePointer { get { return Settings.GetBool("hidepointer", true); } }
    int Best { get { return Settings.GetInt("best", 0); } }

    protected override void OnStart()
    {
        started = true;
        lastTickAt = Environment.TickCount;
    }

    void NewGame()
    {
        quack = new Duck(this);
        dogRect = new Rectangle(-190, 410, 190, 138);
        timer = 0f;
        jumpTime = 0f;
        accum = 0f;
        currentFrame = 0;
        dogGone = false;
        isShooting = 0;
        score = 0;
        posScore = 0;
        retRect = new Rectangle(525, 325, 65, 65);
        exRect = new Rectangle(535, 335, 45, 45);
        center = new Point(557, 357);
        endDogRect = new Rectangle(0, 425, 150, 109);
        cloudRect = new Rectangle[4];
        pointDuckRect = new Rectangle[20];
        layoutFor = -1;
        Relayout();
        lastTickAt = Environment.TickCount;
    }

    // Everything whose place is set by the painted backdrop moves with it. Sprite sizes never
    // scale, so the ducks, the dog and the reticle keep their shape on every card.
    void Relayout()
    {
        int w = GW;
        if (layoutFor == w) return;
        float s = w / (float)BaseW;
        float ratio = layoutFor > 0 ? w / (float)layoutFor : 1f;

        floraRect = new Rectangle(0, 38, w, 500);
        shotRect = new Rectangle(R(113 * s), 607, R(80 * s), 45);
        hitX = R(275 * s);
        scoreX = R(825 * s);
        endDogRect = new Rectangle(w / 2 - 75, endDogRect.Height == 0 ? 425 : endDogRect.Y, 150, 109);

        for (int x = 0; x < 20; x++)
        {
            int px = R((x % 10 * 30 + 415) * s);
            pointDuckRect[x] = new Rectangle(px, x < 10 ? 607 : 632, 20, 20);
        }

        if (layoutFor < 0)
        {
            int cw = R(350 * s);
            cloudRect[0] = new Rectangle(R(-140 * s), 0, cw, 100);
            cloudRect[1] = new Rectangle(R(140 * s), 110, cw, 100);
            cloudRect[2] = new Rectangle(R(420 * s), 0, cw, 100);
            cloudRect[3] = new Rectangle(R(700 * s), 110, cw, 100);
        }
        else
        {
            // resized mid-game: slide what is already on screen across rather than snapping it home
            for (int i = 0; i < cloudRect.Length; i++)
                cloudRect[i] = new Rectangle(R(cloudRect[i].X * ratio), cloudRect[i].Y, R(350 * s), 100);
            if (quack != null)
            {
                int max = w - quack.rect.Width;
                int nx = R(quack.rect.X * ratio);
                quack.rect.X = nx < 0 ? 0 : (nx > max ? max : nx);
            }
        }
        layoutFor = w;
    }

    static int R(float v) { return (int)Math.Round(v); }

    protected override void Changed()
    {
        Relayout();
        base.Changed();
    }

    // ---- frame pump ----
    bool PointerInside()
    {
        if (!IsHandleCreated || IsDisposed) return false;
        Point p = PointToClient(Cursor.Position);
        return p.X >= 0 && p.Y >= 0 && p.X < Width && p.Y < Height;
    }

    bool Awake()
    {
        // A pointer resting motionless over the widget sends no messages, so ask where it is
        // rather than waiting for the next WM_MOUSEMOVE.
        if (PointerInside()) { lastMouseAt = Environment.TickCount; return true; }
        return Environment.TickCount - lastMouseAt < IdleMs;
    }

    bool Playing()
    {
        if (!started || !introStarted || IsCovered()) return false;
        return Awake() || (quack.gameOver && endDogRect.Y > 350);
    }

    protected override int NextFrameDelay()
    {
        if (!started || !introStarted) return -1;
        if (IsCovered()) return CoveredMs;
        return Playing() ? FrameMs : -1;
    }

    // The original ran its logic at XNA's fixed 60 Hz step. Rendering at 30 and stepping the
    // simulation at 60 keeps every ported constant (fly speed, cloud drift, fall time) exact.
    void Advance()
    {
        int now = Environment.TickCount;
        float elapsed = now - lastTickAt;
        lastTickAt = now;
        if (!Playing()) return;
        if (elapsed < 0 || elapsed > 250) elapsed = StepMs;  // resumed after a pause: don't catch up
        accum += elapsed;
        while (accum >= StepMs) { Step(StepMs); accum -= StepMs; }
    }

    void Step(float dt)
    {
        int w = GW;

        // ---- dog intro ----
        timer += dt;
        if (!dogGone && timer > 1000f / 7f)
        {
            currentFrame++;
            // The original walks the dog 10px a tick, which takes about 15 seconds. A widget
            // that greets you for 15 seconds is a widget you uninstall, so it walks 4x faster.
            int stop = w / 2 - 100;
            if (!(currentFrame == 0 || currentFrame == 1 || currentFrame == 5) && dogRect.X <= stop) dogRect.X += 40;
            if (currentFrame > 4 && dogRect.X <= stop) currentFrame = 0;
            if (dogRect.X >= stop + 10 && jumpTime <= 50f) { currentFrame = 5; jumpTime += dt; }
            if (jumpTime > 50f) { currentFrame = 6; dogRect.Y = 345; jumpTime += dt; }
            if (jumpTime > 70f) { dogRect.Y = 360; currentFrame = 7; }
            if (jumpTime > 100f) dogGone = true;
            timer = 0f;
        }
        if (!dogGone) dogSrc = new Rectangle(currentFrame * 55, 0, 55, 47);

        // ---- clouds ----
        for (int x = 0; x < 4; x++)
        {
            cloudRect[x].X -= 1;
            if (cloudRect[x].X + cloudRect[x].Width <= 0) cloudRect[x].X = w;
        }

        if (!dogGone || quack.gameOver)
        {
            if (quack.gameOver && endDogRect.Y > 350) endDogRect.Y -= 2;
            return;
        }

        // ---- duck ----
        quack.Update(dt);
        if (quack.gameOver)
        {
            if (score > Best) Settings.Set("best", score);  // one disk write a game, not one a duck
            return;
        }

        // The shot on offer right now. Ported verbatim: a low duck and a full magazine are worth
        // more, which is the original's scoring, odd as it looks.
        if (quack.isFlying)
            posScore = (quack.rect.Y + 70) * (quack.shot == 3 ? quack.shot : quack.shot + 1);
        if (posScore <= 0) posScore = 0;

        if (isShooting > 0) isShooting--;
    }

    // ---- input ----
    // The screen is the trigger, so it counts as a button: pressing it never starts a drag.
    // The bezel around it stays draggable, which is how the widget gets moved.
    protected override bool IsButton(Point p) { return ScreenRect().Contains(p); }

    protected override void OnMouseMove(MouseEventArgs e)
    {
        base.OnMouseMove(e);
        bool onScreen = ScreenRect().Contains(e.Location);
        Cursor want = onScreen ? (HidePointer ? Blank : Cursors.Cross) : Cursors.Default;
        if (Cursor != want) Cursor = want;

        lastMouseAt = Environment.TickCount;
        if (onScreen) Aim(e.Location);
        if (!introStarted && onScreen)
        {
            introStarted = true;
            lastTickAt = Environment.TickCount;
            Sfx("sniff");
            Render();
            return;
        }
        // Mouse moves arrive far faster than 30 fps; the frame timer does the rest.
        if (Environment.TickCount - lastRenderAt >= FrameMs) Render();
    }

    void Aim(Point device)
    {
        RectangleF scr = ScreenRect();
        if (scr.Width <= 0) return;
        int w = GW;
        float k = scr.Width / w;
        int cx = (int)((device.X - scr.X) / k), cy = (int)((device.Y - scr.Y) / k);
        if (cx < 0) cx = 0; else if (cx > w) cx = w;
        if (cy < 0) cy = 0; else if (cy > 532) cy = 532;  // the original's floor: no shooting the HUD
        center = new Point(cx, cy);
        retRect = new Rectangle(cx - 32, cy - 32, 65, 65);
        exRect = new Rectangle(cx - 22, cy - 22, 45, 45);
    }

    // Firing on the press rather than the release, so the gun goes off when you click. The
    // release becomes OnWidgetClick, which is why that one only ever restarts a finished game.
    protected override void OnMouseDown(MouseEventArgs e)
    {
        base.OnMouseDown(e);
        if (e.Button != MouseButtons.Left || !ScreenRect().Contains(e.Location)) return;
        Aim(e.Location);
        Shoot();
    }

    protected override void OnWidgetClick(Point p)
    {
        if (quack.gameOver && ScreenRect().Contains(p)) { NewGame(); introStarted = true; Render(); }
    }

    void Shoot()
    {
        if (!introStarted || !dogGone || quack.gameOver) return;
        lastMouseAt = Environment.TickCount;
        if (quack.shot == 0) { Sfx("dry"); return; }

        isShooting = 5;
        Sfx("gunshot");
        quack.shot--;

        bool hit = quack.isFlying &&
                   center.X >= quack.rect.X && center.X <= quack.rect.X + 65 &&
                   center.Y >= quack.rect.Y && center.Y <= quack.rect.Y + 71;
        if (hit && quack.lives < quack.isDead.Length)
        {
            quack.isFlying = false;
            Sfx("quack");
            score += posScore;
            quack.isDead[quack.lives] = true;
            quack.lives++;
        }
        Render();
    }

    // CardWidget's own BuildMenu offers a Size submenu of zoom percentages. This widget's three
    // sizes are different shapes, not one shape magnified, so it builds the menu itself.
    protected override void BuildMenu(PopupMenu menu)
    {
        BuildWidgetMenu(menu);
        menu.AddSeparator();
        PopupMenu look = menu.AddSubmenu("Appearance");
        string face = Face;
        foreach (string[] choice in AppearanceChoices)
        {
            string id = choice[0];
            look.AddChoice(choice[1], face == id, delegate { Settings.Set("face", id); Changed(); });
        }
        PopupMenu size = menu.AddSubmenu("Size");
        AddSize(size, "compact", "Compact");
        AddSize(size, "standard", "Standard");
        AddSize(size, "large", "Large");
    }

    void AddSize(PopupMenu menu, string id, string label)
    {
        string want = id;
        menu.AddChoice(label, Settings.Get("size", "standard") == want,
                       delegate { Settings.Set("size", want); Changed(); });
    }

    protected override void BuildWidgetMenu(PopupMenu menu)
    {
        menu.Add("New Game", delegate { NewGame(); introStarted = true; Render(); });
        PopupMenu theme = menu.AddSubmenu("Theme");
        AddTheme(theme, "classic", "Classic");
        AddTheme(theme, "night", "Night");
        AddTheme(theme, "crt", "CRT");
        menu.AddCheck("Sound", !Muted, delegate { Settings.Set("mute", !Muted); });
        menu.AddCheck("Hide Pointer", HidePointer, delegate { Settings.Set("hidepointer", !HidePointer); });
    }

    void AddTheme(PopupMenu menu, string id, string label)
    {
        string t = id;
        menu.AddChoice(label, Theme == t, delegate { Settings.Set("theme", t); Changed(); });
    }

    // ---- drawing ----
    static readonly string[] ShotArt = { "shot0", "shot1", "shot2", "shot3" };

    // CardWidget's own Draw paints a card sized from its fixed W/H; this widget's card is a
    // different shape, so it paints the bezel itself and then hands over to DrawContent.
    protected override void Draw(Graphics g)
    {
        g.CompositingMode = CompositingMode.SourceCopy;
        g.Clear(Color.Transparent);
        g.CompositingMode = CompositingMode.SourceOver;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.TextRenderingHint = TextRenderingHint.AntiAlias;  // ClearType fringes on a layered window
        Size sz = Measure();
        using (GraphicsPath card = RoundRect(new RectangleF(0, 0, sz.Width, sz.Height), Z * 22f))
        using (var b = new SolidBrush(CardBackground(Pal)))
            g.FillPath(b, card);
        DrawContent(g, Pal);
        g.ResetClip();
    }

    protected override void DrawContent(Graphics g, Palette pal)
    {
        lastRenderAt = Environment.TickCount;
        Relayout();
        Advance();

        RectangleF scr = ScreenRect();
        int w = GW;
        float k = scr.Width / w;
        string theme = Theme;

        using (GraphicsPath screen = RoundRect(scr, Z * 6f))
        {
            g.SetClip(screen);
            GraphicsState state = g.Save();
            g.TranslateTransform(scr.X, scr.Y);
            g.ScaleTransform(k, k);
            DrawGame(g, w);
            g.Restore(state);

            // Themes restyle the finished screen, in device pixels so a scanline stays one pixel.
            if (theme == "night") g.FillRectangle(NightWash, scr);
            else if (theme == "crt")
            {
                g.FillRectangle(Scanlines(), scr);
                g.FillPath(Vignette(scr), screen);
            }
            g.ResetClip();
        }
    }

    void DrawGame(Graphics g, int w)
    {
        Pixels(g);
        g.DrawImage(Img("screen"), new Rectangle(0, 0, w, GameH));

        // shells, the HIT row and the two score boxes
        g.DrawImage(Img(ShotArt[quack.shot & 3]), shotRect);
        for (int x = 0; x < 20; x++)
            g.DrawImage(Img("pduck"), pointDuckRect[x], 0, 0, 7, 7, GraphicsUnit.Pixel,
                        quack.isDead[x] ? TintRed : (x == quack.lives ? TintNext : TintPlain));
        DrawAt(g, "HIT:", hitX, 592, Hud, HudFont);
        DrawAt(g, score.ToString(), scoreX, 623, Hud, HudFont);
        DrawAt(g, posScore.ToString(), scoreX, 555, Hud, HudFont);

        if (!dogGone)
        {
            Clouds(g);
            Pixels(g);
            g.DrawImage(Img("flora"), floraRect);
            Sprite(g, Img("dog"), dogRect, dogSrc, false);
        }
        else
        {
            Pixels(g);
            Sprite(g, Img("duck"), quack.rect, quack.sourceRect, quack.flipped);
            if (quack.gameOver) g.DrawImage(Img("endDog"), endDogRect);
            Clouds(g);
            Pixels(g);
            g.DrawImage(Img("flora"), floraRect);
            if (isShooting > 0) g.DrawImage(Img("explode"), exRect);
        }

        if (quack.gameOver)
        {
            Centered(g, w, "Game Over!", 110, Brushes.Black, HudFont);
            Centered(g, w, "Score " + score, 175, Brushes.Black, HudFont);
            Centered(g, w, "Best " + Math.Max(Best, score), 240, Brushes.Black, HudFont);
            Centered(g, w, "Click to play again", 305, Brushes.Black, SmallFont);
        }
        else if (!introStarted) Hint(g, w, "Move here to play");
        else if (!Awake()) Hint(g, w, "Paused");
        else if (!dogGone) Hint(g, w, "Aim with the mouse, left click to shoot");

        // The reticle last, so nothing paints over it.
        if (dogGone && !quack.gameOver && introStarted)
        {
            g.InterpolationMode = InterpolationMode.HighQualityBilinear;
            g.DrawImage(Img("reticle"), retRect);
        }
    }

    void Clouds(Graphics g)
    {
        g.InterpolationMode = InterpolationMode.HighQualityBilinear;
        for (int i = 0; i < cloudRect.Length; i++) g.DrawImage(Img("cloud"), cloudRect[i]);
    }

    // Pixel art stays crisp when it is scaled up; smoothing turns the NES sprites to mush.
    static void Pixels(Graphics g)
    {
        g.InterpolationMode = InterpolationMode.NearestNeighbor;
        g.PixelOffsetMode = PixelOffsetMode.Half;
    }

    void Hint(Graphics g, int w, string s)
    {
        SizeF m = g.MeasureString(s, HintFont);
        var box = new RectangleF((w - m.Width) / 2f - 24, 210, m.Width + 48, m.Height + 20);
        using (GraphicsPath p = RoundRect(box, 22)) g.FillPath(Scrim, p);
        g.DrawString(s, HintFont, Brushes.White, box.X + 24, box.Y + 10);
    }

    static void DrawAt(Graphics g, string s, int x, int y, Brush brush, Font f)
    {
        g.DrawString(s, f, brush, x, y);
    }

    static void Centered(Graphics g, int w, string s, int y, Brush brush, Font f)
    {
        SizeF m = g.MeasureString(s, f);
        g.DrawString(s, f, brush, (w - m.Width) / 2f, y);
    }

    // ---- themes ----
    static readonly Brush NightWash = new SolidBrush(Color.FromArgb(105, 12, 20, 72));

    // One 1 x 3 tile, so the darkened row lands on every third device pixel however the card
    // is scaled. Cheap enough to fill every frame.
    static TextureBrush scanlines;
    static TextureBrush Scanlines()
    {
        if (scanlines == null)
        {
            var tile = new Bitmap(1, 3, PixelFormat.Format32bppPArgb);
            tile.SetPixel(0, 0, Color.FromArgb(16, 0, 0, 0));
            tile.SetPixel(0, 1, Color.FromArgb(0, 0, 0, 0));
            tile.SetPixel(0, 2, Color.FromArgb(62, 0, 0, 0));
            scanlines = new TextureBrush(tile, WrapMode.Tile);
        }
        return scanlines;
    }

    PathGradientBrush vignette;
    RectangleF vignetteFor;

    PathGradientBrush Vignette(RectangleF r)
    {
        if (vignette == null || vignetteFor != r)
        {
            if (vignette != null) vignette.Dispose();
            using (var p = new GraphicsPath())
            {
                p.AddEllipse(RectangleF.Inflate(r, r.Width * 0.22f, r.Height * 0.22f));
                vignette = new PathGradientBrush(p);
            }
            vignette.CenterPoint = new PointF(r.X + r.Width / 2f, r.Y + r.Height / 2f);
            vignette.CenterColor = Color.FromArgb(0, 0, 0, 0);
            vignette.SurroundColors = new[] { Color.FromArgb(105, 0, 0, 0) };
            vignetteFor = r;
        }
        return vignette;
    }

    // ---- cached GDI+ objects: DrawContent runs 30 times a second and must not allocate ----
    static readonly Brush Hud = new SolidBrush(Color.FromArgb(64, 191, 255));
    static readonly Brush Scrim = new SolidBrush(Color.FromArgb(150, 0, 0, 0));
    static readonly Font HudFont = new Font("Consolas", 40f, FontStyle.Bold, GraphicsUnit.Pixel);
    static readonly Font SmallFont = new Font("Consolas", 26f, FontStyle.Bold, GraphicsUnit.Pixel);
    static readonly Font HintFont = new Font("Segoe UI Semibold", 30f, GraphicsUnit.Pixel);

    protected override void Dispose(bool disposing)
    {
        if (disposing && vignette != null) { vignette.Dispose(); vignette = null; }
        base.Dispose(disposing);
    }

    // TileFlipXY stops a neighbouring frame of the sprite sheet bleeding in at the seam.
    static readonly ImageAttributes NoBleed = Attrs(Color.White);
    // The score ducks are one white sprite recoloured per state, as the original did with
    // SpriteBatch's colour parameter.
    static readonly ImageAttributes TintPlain = Attrs(Color.White);
    static readonly ImageAttributes TintRed = Attrs(Color.Red);
    static readonly ImageAttributes TintNext = Attrs(Color.LightSkyBlue);

    static ImageAttributes Attrs(Color c)
    {
        var a = new ImageAttributes();
        a.SetWrapMode(WrapMode.TileFlipXY);
        if (c != Color.White)
        {
            var m = new ColorMatrix();
            m.Matrix00 = c.R / 255f;
            m.Matrix11 = c.G / 255f;
            m.Matrix22 = c.B / 255f;
            a.SetColorMatrix(m);
        }
        return a;
    }

    static void Sprite(Graphics g, Bitmap img, Rectangle dst, Rectangle src, bool flip)
    {
        if (src.Width <= 0 || src.Height <= 0) return;
        if (!flip)
        {
            g.DrawImage(img, dst, src.X, src.Y, src.Width, src.Height, GraphicsUnit.Pixel, NoBleed);
            return;
        }
        // GDI+ has no SpriteEffects.FlipHorizontally: map the source onto a parallelogram whose
        // top-left corner is the destination's top-right.
        var pts = new PointF[]
        {
            new PointF(dst.Right, dst.Top),
            new PointF(dst.Left, dst.Top),
            new PointF(dst.Right, dst.Bottom)
        };
        g.DrawImage(img, pts, new RectangleF(src.X, src.Y, src.Width, src.Height), GraphicsUnit.Pixel, NoBleed);
    }

    static Cursor blank;
    static Cursor Blank
    {
        get
        {
            if (blank == null)
                using (var bmp = new Bitmap(32, 32, PixelFormat.Format32bppArgb))
                    blank = new Cursor(bmp.GetHicon());
            return blank;
        }
    }

    // ---- the duck, ported from Duck.cs ----
    sealed class Duck
    {
        public Rectangle rect;
        public Rectangle sourceRect;
        public bool isFlying = true;
        public bool flipped;
        public readonly bool[] isDead = new bool[20];
        public int lives;
        public bool gameOver;
        public int shot = 3;

        readonly DuckHuntWidget owner;
        readonly Random rand = new Random();
        float timer;
        int currentFrame, flyTime, leftRight, fallTime;

        public Duck(DuckHuntWidget owner)
        {
            this.owner = owner;
            rect = new Rectangle(Spawn(), 450, 74, 70);
            sourceRect = new Rectangle(0, 0, 34, 31);
        }

        // The original picked 200..800 of 1100; keep that as a share of however wide the sky is.
        int Spawn()
        {
            float s = owner.GW / (float)BaseW;
            return rand.Next((int)(200 * s), (int)(801 * s));
        }

        public void Update(float deltaTime)
        {
            timer += deltaTime;
            if (timer <= 1000f / 20f) return;
            int right = owner.GW - 74;

            if (isFlying)
            {
                currentFrame++;
                if (currentFrame > 2) currentFrame = 0;
                timer = 0f;

                if (flyTime == 0) { leftRight = rand.Next(2); flyTime = 10; }
                if (rect.X >= right) { leftRight = 0; flyTime = 10; }
                if (rect.X <= 0) { leftRight = 1; flyTime = 10; }

                if (leftRight == 0) { rect.X -= 15; flipped = true; }
                else { rect.X += 15; flipped = false; }
                rect.Y -= 10;
                flyTime--;

                if (rect.Y <= -71) Respawn(true);
            }
            else
            {
                // The original never resets the timer while the duck falls, so this branch runs
                // every frame rather than every 50 ms. Kept: it is what makes the fall look fast.
                if (fallTime <= 50) currentFrame = 6;
                else if (rect.Y <= 450) { currentFrame = 7; rect.Y += 5; }
                else { fallTime = 0; Respawn(false); }
                fallTime++;
            }

            sourceRect = new Rectangle(currentFrame * 34, 0, 34, 31);
        }

        void Respawn(bool escaped)
        {
            rect.X = Spawn();
            rect.Y = 450;
            if (escaped) lives++;
            if (lives >= 20) { gameOver = true; isFlying = false; return; }
            isFlying = true;
            if (escaped && shot == 3) return;  // nothing to reload
            owner.Sfx("cock");
            shot = 3;
        }
    }

    // ---- embedded art and sound ----
    static Dictionary<string, Bitmap> images;

    static Bitmap Img(string name)
    {
        if (images == null)
        {
            images = new Dictionary<string, Bitmap>();
            for (int i = 0; i < Art.Length; i += 2) images[Art[i]] = Decode(Art[i + 1]);
        }
        return images[name];
    }

    static Bitmap Decode(string base64)
    {
        byte[] raw = Convert.FromBase64String(base64);
        using (var ms = new MemoryStream(raw))
        using (var src = new Bitmap(ms))
        {
            // Copy out so the bitmap does not hold the stream open, and pin it to 96 dpi so a
            // high-dpi screen does not quietly rescale the sprite sheets.
            var copy = new Bitmap(src.Width, src.Height, PixelFormat.Format32bppPArgb);
            copy.SetResolution(96f, 96f);
            using (Graphics g = Graphics.FromImage(copy))
            {
                g.CompositingMode = CompositingMode.SourceCopy;
                g.InterpolationMode = InterpolationMode.NearestNeighbor;
                g.PixelOffsetMode = PixelOffsetMode.Half;
                g.DrawImage(src, new Rectangle(0, 0, src.Width, src.Height));
            }
            return copy;
        }
    }

    static Dictionary<string, SoundPlayer> sounds;

    // ponytail: SoundPlayer is winmm PlaySound, which keeps one async sound per process, so a
    // quack cuts the gunshot short. Swap in waveOut or XAudio2 if the overlap ever matters.
    internal void Sfx(string name)
    {
        if (Muted) return;
        try
        {
            if (sounds == null) sounds = new Dictionary<string, SoundPlayer>();
            SoundPlayer p;
            if (!sounds.TryGetValue(name, out p))
            {
                for (int i = 0; i < Audio.Length; i += 2)
                    if (Audio[i] == name)
                    {
                        p = new SoundPlayer(new MemoryStream(Convert.FromBase64String(Audio[i + 1])));
                        p.Load();
                        break;
                    }
                if (p == null) return;
                sounds[name] = p;
            }
            p.Play();
        }
        catch (Exception)
        {
            // A machine with no audio device must not take the widget down with it.
        }
    }

